"""C1 static, research-only Market Risk Context contract. No live retrieval."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'data/research'
CATEGORIES={'GEOPOLITICAL':['war','military escalation','sanctions','trade restrictions linked to conflict'],'MONETARY_POLICY':['RBI','major central bank','rate/liquidity action'],'FISCAL_POLICY':['Budget','tax','fiscal','subsidy/tariff'],'ECONOMIC_GROWTH':['GDP','inflation','employment','PMI','growth shock'],'FINANCIAL_SYSTEM':['bank stress','sovereign/default','liquidity','credit disruption'],'COMMODITY_ENERGY':['crude','gas/energy','commodity supply disruption'],'TRADE_POLICY':['tariff','export/import restriction','trade escalation'],'TECHNOLOGY_SYSTEMIC':['semiconductor restriction','AI/technology regulation','systemic cyber/infrastructure disruption'],'PUBLIC_HEALTH_NATURAL_DISASTER':['pandemic','severe broad economic natural disaster'],'GLOBAL_MARKET_STRESS':['global dislocation','volatility shock','cross-market selloff']}
def run():
 taxonomy={'version':'C1_V1','categories':CATEGORIES,'event_context_boundary':'Company events affect one company; sector events primarily affect an industry; Market Risk Context requires plausible broad portfolio/market impact.','not_market_risk_examples':['company earnings miss','single-stock technical failure','ordinary sector-specific event']}
 contract={'contract_version':'C1_MARKET_RISK_CONTEXT_V1','informational_only':True,'live_data_fetching_implemented':False,'item_schema':{'required':['market_risk_event_id','category','headline_or_short_title','summary','event_timestamp','published_timestamp','observed_at_timestamp','source_name','source_type','source_url_or_reference','geographic_scope','market_scope','direction','materiality','confidence','freshness','status','expected_horizon','evidence_summary','possible_market_channels','affected_asset_context','informational_only'],'enums':{'direction':['RISK_POSITIVE','RISK_NEGATIVE','MIXED','UNCLEAR'],'materiality':['LOW','MODERATE','HIGH','SEVERE'],'confidence':['LOW','MODERATE','HIGH'],'freshness':['FRESH','RECENT','STALE'],'status':['ACTIVE','MONITOR','RESOLVED','UNKNOWN'],'expected_horizon':['INTRADAY','DAYS','WEEKS','LONGER','UNKNOWN']}},'source_hierarchy':{'TIER_1_PRIMARY_OFFICIAL':['RBI','Government of India / Ministry of Finance','PIB','SEBI','major central banks','official government, defense, regulatory or exchange notices'],'TIER_2_HIGH_QUALITY_NEWS':['reputable global financial news','reputable Indian business/financial news'],'TIER_3_SECONDARY_CONTEXT':['reputable broader media','institutional commentary']},'materiality_semantics':{'LOW':'limited likely broad-market impact','MODERATE':'plausible sentiment, macro-variable or meaningful-subset impact','HIGH':'credible potential for broad repricing, volatility or gap risk','SEVERE':'exceptional systemic cross-market/broad-portfolio risk'},'confidence_semantics':{'HIGH':'authoritative or multiple strong corroborating sources with clear facts','MODERATE':'credible sources but implications/materiality uncertain','LOW':'credible enough to monitor, evidence or interpretation incomplete'},'freshness_rules':{'FRESH':'<=24 hours since published/confirmed','RECENT':'>24 hours and <=7 days','STALE':'>7 days','status_note':'ACTIVE ongoing risks may remain active despite stale news freshness'},'overall_context':{'levels':['NORMAL','ELEVATED','HIGH','SEVERE','NOT_AVAILABLE'],'NORMAL':'successful source checks with no active MODERATE/HIGH/SEVERE broad risk','ELEVATED':'one or more credible MODERATE risks or limited HIGH risk','HIGH':'one or more credible HIGH broad-market risks','SEVERE':'active exceptional systemic risk','NOT_AVAILABLE':'evaluation/retrieval unreliable; never infer NORMAL'},'guardrails':{'market_risk_context_affects_qualification':False,'market_risk_context_affects_priority':False,'market_risk_context_affects_sizing':False,'market_risk_context_affects_allocation':False,'market_risk_context_affects_stops':False},'payload':{'market_risk_context':{'overall_level':'NORMAL|ELEVATED|HIGH|SEVERE|NOT_AVAILABLE','generated_at':'ISO-8601','active_event_count':'integer','high_materiality_count':'integer','categories':'category status map','top_events':'maximum 3 structured items','gap_risk_note':'string','informational_only':True}},'display_policy':'Show overall level and top three material/fresh active events with category, timestamp/freshness, confidence and concise channel/evidence summary.','interpretation_labels':{'reference':'External-risk context is informational and does not predict stock returns.','gap_risk':'Elevated broad risk can mean overnight realized loss exceeds defined technical stop risk.'},'llm_role_later':['normalization','summary','channel extraction','evidence-bound qualitative classification','deduplication'],'llm_prohibitions':['invent events/sources','predict returns','override missing evidence','fabricate confirmation']}
 (R/'c1_market_risk_taxonomy.json').write_text(json.dumps(taxonomy,indent=2)+'\n');(R/'c1_market_risk_contract.json').write_text(json.dumps(contract,indent=2)+'\n')
 report=['# C1 Market Risk Context Contract','', 'Forward-looking, live, source-based and evidence-backed — but informational only. No live sources were fetched and no historical backtest/PIT reconstruction was attempted.','', '## Taxonomy','', '\n'.join(f'- **{k}**: {", ".join(v)}' for k,v in CATEGORIES.items()),'', '## Source and evidence standard','', 'Tier 1 official/primary sources are preferred; Tier 2 reputable financial news supports inherently news-driven events; Tier 3 is secondary context. Every item retains what/when/source/plausible channel; materiality is never fabricated.','', '## Boundaries and guardrails','', 'Market Risk Context concerns broad market/portfolio risk, not company/sector event context, qualification, priority, sizing, allocation, stops or return prediction.','', '## Readiness','', '`C2_LIVE_MARKET_RISK_CONTEXT = READY`: taxonomy, source hierarchy, evidence semantics and compact payload are frozen; C2 can implement retrieval and provenance without methodological ambiguity.']
 (R/'c1_market_risk_context_report.md').write_text('\n'.join(report)+'\n');print({'categories':len(CATEGORIES),'C2':'READY'})
if __name__=='__main__':run()
